SELECT DISTINCT sm.id, sm.redirect, sm.be_hidden, sm.menu_name, sm.priority, sm.icon, sm.parent_id, ra.req_url FROM sys_menu_tenant AS sm LEFT JOIN sys_tenant_role_resource rr ON sm.id = rr.resource_id AND rr.resource_type = 'MENU' LEFT JOIN sys_tenant_role r ON rr.role_id = r.id INNER JOIN sys_resource_api_tenant ra ON sm.id = ra.resource_id AND ra.resource_type = 'MENU'
AND ( (sm.be_unauth = 0 AND r.id in
#{item}
) OR (sm.be_unauth = 1))
AND sm.be_unauth = 1
and r.tenant_id = #{tenantId,jdbcType=CHAR}
ORDER BY sm.priority, sm.parent_id ASC

SELECT DISTINCT sm.id, sm.redirect, sm.be_hidden, sm.menu_name, sm.priority, sm.icon, sm.parent_id, ra.req_url FROM sys_menu_tenant sm LEFT JOIN sys_tenant_role_resource rr ON sm.id = rr.resource_id AND rr.resource_type = 'MENU' LEFT JOIN sys_tenant_role r ON rr.role_id = r.id INNER JOIN sys_resource_api_tenant ra ON sm.id = ra.resource_id AND ra.resource_type = 'MENU'
sm.menu_type = #{menuType,jdbcType=CHAR} AND ( (sm.be_unauth = 0 AND r.id in
#{item}
