sm.menu_type = #{menuType,jdbcType=CHAR} AND sm.be_unauth = 1
AND sm.be_hidden = 0 and r.tenant_id = #{tenantId,jdbcType=CHAR}
ORDER BY sm.priority ,sm.parent_id ASC

SELECT m.id,m.menu_name,m.parent_id,m.priority FROM sys_menu_tenant m inner join sys_tenant_menu tm on tm.menu_id = m.id LEFT JOIN sys_tenant_role_resource rr ON m.id = rr.resource_id AND rr.resource_type = 'MENU' LEFT JOIN sys_tenant_role r ON rr.role_id = r.id INNER JOIN sys_resource_api_tenant ra ON (ra.resource_id = m.id AND ra.resource_type = 'MENU') WHERE m.be_unauth = 0 and tm.tenant_id = #{tenantId,jdbcType=CHAR} and r.id in
#{item}
GROUP BY m.id

SELECT (IF(sb.be_unauth = 1, 'RESOURCE_NO_NEED_ROLE', CONCAT(GROUP_CONCAT(srr.role_id)))) role_ids
FROM sys_resource_api_tenant api
LEFT JOIN sys_tenant_role_resource srr ON api.resource_id = srr.resource_id AND api.resource_type = srr.resource_type AND srr.tenant_id = #{tenantId,jdbcType=CHAR}
LEFT JOIN sys_button_tenant sb ON api.resource_id = sb.id
WHERE api.resource_type = 'BUTTON' AND api.req_url = #{url,jdbcType=VARCHAR} and api.req_method=#{reqMethod,jdbcType=VARCHAR}
GROUP BY api.req_url, api.req_method, sb.be_unauth
